import layoutManifestProps from './layout.properties.json';

export const variants = layoutManifestProps?.containerModifiers?.properties?.variant?.items?.enum.filter(Boolean);
export const verticalSpaces = layoutManifestProps?.containerModifiers?.properties?.verticalSpace?.items?.enum.filter(Boolean);

export function containerModifiers(props = {}) {
    let str = '';
    const { containerModifiers: { variant, verticalSpace, fullwidthBackground } = {}} = props;
    if (!variant && !verticalSpace && !fullwidthBackground) return str;
    const mods = [];
    if (variant && variants.includes(variant)) mods.push(variant);
    if (verticalSpace && verticalSpaces.includes(verticalSpace)) mods.push(verticalSpace);
    if (fullwidthBackground) mods.push('fullwidth-background');
    if (mods.length) str = ` data-cm="${mods.join(':')}" `;
    return str;
}
